<template><section><div class="page-heading"><div><h1>员工</h1><p>管理员工状态、所属部门和初始登录凭据。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">创建员工</el-button></div><div class="filters"><el-input v-model="query" clearable placeholder="搜索员工邮箱" :prefix-icon="Search"/><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option label="在职" value="active"/><el-option label="停用" value="disabled"/><el-option label="已离职" value="terminated"/></el-select></div><el-table v-loading="loading" :data="filtered"><el-table-column prop="email" label="邮箱" min-width="230"/><el-table-column label="员工 ID" width="120"><template #default="{row}">{{ maskEmployeeId(row.id) }}</template></el-table-column><el-table-column label="部门" min-width="140"><template #default="{row}">{{ departmentName(row.department_id) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="首次改密" width="110"><template #default="{row}">{{ row.must_change_password ? '待完成' : '已完成' }}</template></el-table-column><el-table-column label="操作" width="360" fixed="right"><template #default="{row}"><el-button text :icon="View" @click="router.push({name:'EnterpriseEmployeeDetail',params:{id:row.id}})">详情</el-button><el-button text :icon="Edit" :disabled="row.status==='terminated'" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status==='active'" text type="warning" @click="setStatus(row,'disabled')">停用</el-button><el-button v-else-if="row.status==='disabled'" text type="success" @click="setStatus(row,'active')">恢复</el-button><el-button text :icon="Key" type="warning" :disabled="row.status==='terminated'" @click="resetPassword(row)">重置密码</el-button><el-button text type="danger" :disabled="row.status==='terminated'" @click="terminate(row)">离职</el-button></template></el-table-column></el-table><el-alert v-if="loadError" type="error" :title="loadError" :closable="false" class="load-error"><el-button size="small" @click="load">重试</el-button></el-alert><el-empty v-else-if="!loading&&!filtered.length" description="暂无匹配员工"/>
<el-dialog v-model="createVisible" title="创建员工" width="min(92vw, 500px)" @closed="resetCreate"><el-alert title="初始密码仅在创建成功后的交付卡片中显示一次，请立即复制并通过安全渠道交付员工。" type="warning" :closable="false" class="notice"/><el-form ref="createFormRef" :model="createForm" :rules="createRules" label-position="top"><el-form-item label="邮箱" prop="email"><el-input v-model="createForm.email" autocomplete="off"/></el-form-item><el-form-item label="初始密码" prop="initial_password"><el-input v-model="createForm.initial_password" type="password" show-password autocomplete="new-password"><template #append><el-button data-testid="generate-initial-password" @click="createForm.initial_password=generateInitialPassword()">随机生成</el-button></template></el-input></el-form-item><el-form-item label="部门"><el-select v-model="createForm.department_id" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createEmployee">创建</el-button></template></el-dialog>
<el-dialog v-model="editVisible" title="编辑员工" width="min(92vw, 500px)"><el-form label-position="top"><el-form-item label="邮箱"><el-input :model-value="editing?.email" disabled/></el-form-item><el-form-item label="部门"><el-select v-model="editDepartment" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEmployee">保存</el-button></template></el-dialog>
<el-dialog v-model="deliveryVisible" title="初始密码交付" width="min(92vw, 520px)" data-testid="initial-password-delivery" @closed="clearDelivery"><el-alert title="系统当前不会自动发送邮件，请通过安全渠道将初始密码交付员工；首次登录后须立即修改。" type="warning" :closable="false" class="notice"/><el-descriptions v-if="delivery" :column="1" border><el-descriptions-item label="邮箱"><span data-testid="delivery-email">{{ delivery.email }}</span></el-descriptions-item><el-descriptions-item label="初始密码"><span class="mono" data-testid="delivery-password">{{ delivery.password }}</span></el-descriptions-item><el-descriptions-item label="入口域名"><span data-testid="delivery-origin">{{ delivery.origin }}</span></el-descriptions-item></el-descriptions><div v-if="manualCopyText" class="manual-copy"><p role="alert">自动复制失败，请在下方文本框中手动复制交付信息。</p><textarea ref="manualCopyInput" data-testid="manual-copy-text" :value="manualCopyText" readonly aria-label="交付信息（手动复制）"/></div><template #footer><el-button @click="copyDelivery">复制交付信息</el-button><el-button type="primary" @click="deliveryVisible=false">我已保存，关闭</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{computed,nextTick,onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import type{FormInstance,FormRules,TagProps}from'element-plus';import{ElMessage,ElMessageBox}from'element-plus';import{Edit,Key,Plus,Search,View}from'@element-plus/icons-vue';import{enterpriseAPI,isEnterpriseEmployeeDepartmentInvalid,isEnterpriseEmployeeVersionConflict}from'@/api/enterprise';import{validatePassword}from'@/features/enterprise/validation';import type{EnterpriseDepartment,EnterpriseEmployee}from'@/types/enterprise';const router=useRouter();const employees=ref<EnterpriseEmployee[]>([]),departments=ref<EnterpriseDepartment[]>([]),loading=ref(false),loadError=ref(''),saving=ref(false),query=ref(''),statusFilter=ref(''),createVisible=ref(false),editVisible=ref(false),createFormRef=ref<FormInstance>(),editing=ref<EnterpriseEmployee>(),editDepartment=ref<number|null>(null);const maskEmployeeId=(_id:number)=>'••••••••••';const createForm=reactive({email:'',initial_password:'',department_id:null as number|null});const createRules:FormRules={email:[{required:true,type:'email',message:'请输入有效邮箱',trigger:'blur'}],initial_password:[{validator:(_r,_v,cb)=>{const m=validatePassword(createForm.initial_password);m?cb(new Error(m)):cb()},trigger:'blur'}]};const INITIAL_PASSWORD_CHARSET='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';function generateInitialPassword():string{const bytes=new Uint32Array(12);crypto.getRandomValues(bytes);return Array.from(bytes,b=>INITIAL_PASSWORD_CHARSET[b%INITIAL_PASSWORD_CHARSET.length]).join('')}
const deliveryVisible=ref(false),delivery=ref<{email:string;password:string;origin:string}|null>(null),manualCopyText=ref(''),manualCopyInput=ref<HTMLTextAreaElement|null>(null);function showDelivery(email:string,password:string){manualCopyText.value='';delivery.value={email,password,origin:window.location.origin};deliveryVisible.value=true}function clearDelivery(){delivery.value=null;manualCopyText.value=''}
async function copyDelivery(){if(!delivery.value)return;const text=`邮箱：${delivery.value.email}\n初始密码：${delivery.value.password}\n入口域名：${delivery.value.origin}`;try{if(!navigator.clipboard?.writeText)throw new Error('clipboard unavailable');await navigator.clipboard.writeText(text);manualCopyText.value='';ElMessage.success('交付信息已复制')}catch{manualCopyText.value=text;ElMessage.error('无法自动复制，请使用下方文本框手动复制');await nextTick();manualCopyInput.value?.focus();manualCopyInput.value?.select()}}
const filtered=computed(()=>employees.value.filter(e=>(!query.value||e.email.toLowerCase().includes(query.value.toLowerCase()))&&(!statusFilter.value||e.status===statusFilter.value)));const departmentName=(id?:number|null)=>departments.value.find(d=>d.id===id)?.name||'未分配';const statusLabel=(s:string)=>({active:'在职',disabled:'停用',terminated:'已离职'}[s]||s);const statusType=(s:string):TagProps['type']=>s==='active'?'success':s==='disabled'?'warning':'info';async function load(){loading.value=true;loadError.value='';try{[employees.value,departments.value]=await Promise.all([enterpriseAPI.listEmployees({suppressUnavailableRedirect:true}),enterpriseAPI.listDepartments({suppressUnavailableRedirect:true})])}catch(error){loadError.value=(error as{message?:string})?.message||'员工列表加载失败'}finally{loading.value=false}}function openCreate(){resetCreate();createVisible.value=true}function resetCreate(){createForm.email='';createForm.initial_password='';createForm.department_id=null;createFormRef.value?.clearValidate()}async function createEmployee(){if(!await createFormRef.value?.validate().catch(()=>false))return;saving.value=true;try{const created=await enterpriseAPI.createEmployee({...createForm});createVisible.value=false;showDelivery(created.email,createForm.initial_password);resetCreate();ElMessage.success('员工已创建');await load()}finally{saving.value=false}}
async function resetPassword(row:EnterpriseEmployee){await ElMessageBox.confirm(`确认为 ${row.email} 重置密码？将生成新的初始密码并撤销其全部会话，员工下次登录须使用新初始密码。`,'重置员工密码',{type:'warning'});const result=await enterpriseAPI.resetEmployeePassword(row.id);showDelivery(row.email,result.initial_password)}
function openEdit(row:EnterpriseEmployee){editing.value=row;editDepartment.value=row.department_id??null;editVisible.value=true}async function handleEmployeeVersionConflict(error:unknown){if(!isEnterpriseEmployeeVersionConflict(error))throw error;ElMessage.warning('该员工已被其他管理员修改，已刷新为最新数据，请重新操作。');await load()}async function saveEmployee(){if(!editing.value)return;const target=editing.value;saving.value=true;try{await enterpriseAPI.updateEmployee(target.id,{status:target.status==='disabled'?'disabled':'active',department_id:editDepartment.value,version:target.version});editVisible.value=false;ElMessage.success('员工信息已更新');await load()}catch(error){if(isEnterpriseEmployeeVersionConflict(error)){await handleEmployeeVersionConflict(error);const latest=employees.value.find(e=>e.id===target.id);if(latest){editing.value=latest;editDepartment.value=latest.department_id??null}}else if(isEnterpriseEmployeeDepartmentInvalid(error)){ElMessage.error('所选部门无效，请重新选择部门后重试')}else{editVisible.value=false;ElMessage.error((error as{message?:string})?.message||'员工信息更新失败')}}finally{saving.value=false}}async function setStatus(row:EnterpriseEmployee,status:'active'|'disabled'){try{await enterpriseAPI.updateEmployee(row.id,{status,department_id:row.department_id??null,version:row.version});ElMessage.success(status==='active'?'员工已恢复':'员工已停用');await load()}catch(error){await handleEmployeeVersionConflict(error)}}async function terminate(row:EnterpriseEmployee){await ElMessageBox.confirm(`确认将 ${row.email} 标记为离职？该操作会撤销其会话。`,'员工离职',{type:'warning'});await enterpriseAPI.terminateEmployee(row.id);ElMessage.success('员工已离职');await load()}onMounted(load);</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}.page-heading h1{margin:0 0 6px;font-size:26px}.page-heading p{margin:0;color:#64748b}.filters{display:flex;gap:12px;margin-bottom:18px}.filters .el-input{max-width:340px}.filters .el-select{width:160px}.notice{margin-bottom:18px}.load-error{margin-top:12px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.06em}.manual-copy{margin-top:16px}.manual-copy p{margin:0 0 8px;color:#b42318}.manual-copy textarea{box-sizing:border-box;width:100%;min-height:100px;padding:10px;border:1px solid #94a3b8;border-radius:4px;resize:vertical;font:inherit}@media(max-width:640px){.page-heading,.filters{flex-direction:column}.page-heading .el-button,.filters .el-input,.filters .el-select{width:100%;max-width:none}}</style>
